// See engine_shim.h. Replaces daemon shared/CommonProxies.cpp and shared/server/sg_api.cpp (all
// IPC to the engine), and overrides the BUILD_VM FS::PakPath::ReadFile (an IPC call too) in a
// weakened copy of FileSystem.cpp.o. Only the engine syscalls the parsers use are implemented;
// every other symbol of the replaced objects is generated by mayhem/gen_engine_stubs.py as an
// abort() that names it, so an unexpected engine call is loud instead of silently wrong.
#include "common/Common.h"
#include "common/FileSystem.h"
#include "engine_shim.h"

#include <cstdio>
#include <cstdlib>
#include <map>
#include <unordered_map>

namespace {
struct OpenFile { std::string data; size_t pos = 0; };
std::map<std::string, std::string>& Files() { static std::map<std::string, std::string> f; return f; }
std::map<int, OpenFile>& Handles() { static std::map<int, OpenFile> h; return h; }
int nextHandle = 1;
bool logEnabled() { static bool on = getenv("UNV_FUZZ_LOG") != nullptr; return on; }

int OpenRead(const char* path, fileHandle_t* f) {
	auto it = Files().find(path);
	if (it == Files().end()) {
		if (f) *f = 0;
		return -1;
	}
	if (f) {
		int h = nextHandle++;
		Handles()[h] = OpenFile{it->second, 0};
		*f = h;
	}
	return static_cast<int>(it->second.size());
}
} // namespace

namespace FuzzEngine {
void ResetFiles() { Files().clear(); Handles().clear(); nextHandle = 1; }
void SetFile(const std::string& path, const std::string& content) { Files()[path] = content; }
}

// ---- file system syscalls ----
int trap_FS_FOpenFile(const char* qpath, fileHandle_t* f, fsMode_t mode) {
	if (mode != fsMode_t::FS_READ) { if (f) *f = 0; return -1; }
	return OpenRead(qpath, f);
}
int trap_FS_OpenPakFile(Str::StringRef path, fileHandle_t& f) { return OpenRead(path.c_str(), &f); }
int trap_FS_Read(void* buffer, int len, fileHandle_t f) {
	auto it = Handles().find(f);
	if (it == Handles().end() || len <= 0) return 0;
	OpenFile& o = it->second;
	size_t n = std::min<size_t>(len, o.data.size() - o.pos);
	memcpy(buffer, o.data.data() + o.pos, n);
	o.pos += n;
	return static_cast<int>(n);
}
int trap_FS_Write(const void*, int, fileHandle_t) { return 0; }
int trap_FS_Seek(fileHandle_t f, int offset, fsOrigin_t origin) {
	auto it = Handles().find(f);
	if (it == Handles().end()) return -1;
	OpenFile& o = it->second;
	long base = origin == fsOrigin_t::FS_SEEK_CUR ? (long)o.pos : origin == fsOrigin_t::FS_SEEK_END ? (long)o.data.size() : 0;
	long p = base + offset;
	if (p < 0 || p > (long)o.data.size()) return -1;
	o.pos = p;
	return 0;
}
int trap_FS_Tell(fileHandle_t f) { auto it = Handles().find(f); return it == Handles().end() ? -1 : (int)it->second.pos; }
int trap_FS_FileLength(fileHandle_t f) { auto it = Handles().find(f); return it == Handles().end() ? -1 : (int)it->second.data.size(); }
void trap_FS_FCloseFile(fileHandle_t f) { Handles().erase(f); }
int trap_FS_GetFileList(const char*, const char*, char* listbuf, int bufsize) { if (bufsize > 0) listbuf[0] = 0; return 0; }
int trap_FS_GetFileListRecursive(const char*, const char*, char* listbuf, int bufsize) { if (bufsize > 0) listbuf[0] = 0; return 0; }
bool trap_FindPak(const char*) { return false; }
bool trap_FS_LoadPak(const char*, const char*) { return false; }
void trap_SendConsoleCommand(const char*) {}
void trap_SendServerCommand(int, const char*) {}
int trap_Milliseconds() { return 0; }

// ---- logging: dropped unless UNV_FUZZ_LOG is set ----
namespace Log {
void Dispatch(Event event, int) { if (logEnabled()) fprintf(stderr, "%s\n", event.text.c_str()); }
}

// ---- cvars: a local table, as before the engine handshake ----
namespace Cvar {
namespace {
struct Rec { CvarProxy* cvar; std::string value; };
std::unordered_map<std::string, Rec>& Map() { static std::unordered_map<std::string, Rec> m; return m; }
}
bool Register(CvarProxy* cvar, const std::string& name, std::string, int, const std::string& defaultValue) {
	Map()[name] = {cvar, defaultValue};
	return true;
}
// Engine-owned cvars the VM reads by name (daemon Log.cpp in BUILD_VM). Log suppression is off so
// one input's warnings can never change how a later input is logged.
const std::unordered_map<std::string, std::string>& EngineCvars() {
	static const std::unordered_map<std::string, std::string> m = {
		{"logs.writeSrcLocation.all", "0"}, {"logs.writeSrcLocation.debug", "0"},
		{"logs.writeSrcLocation.notice", "0"}, {"logs.writeSrcLocation.verbose", "0"},
		{"logs.writeSrcLocation.warn", "0"}, {"logs.suppression.enabled", "0"},
		{"logs.suppression.bufferSize", "1"}, {"logs.suppression.count", "1"},
		{"logs.suppression.interval", "1"},
	};
	return m;
}
std::string GetValue(const std::string& name) {
	auto it = Map().find(name);
	if (it != Map().end()) return it->second.value;
	auto e = EngineCvars().find(name);
	return e == EngineCvars().end() ? "" : e->second;
}
void SetValue(const std::string&, const std::string&) {}
bool AddFlags(const std::string& name, int) { return Map().count(name) != 0; }
}
void trap_Cvar_Set(const char*, const char*) {}
int trap_Cvar_VariableIntegerValue(const char* name) { return atoi(Cvar::GetValue(name).c_str()); }
float trap_Cvar_VariableValue(const char* name) { return atof(Cvar::GetValue(name).c_str()); }
void trap_Cvar_VariableStringBuffer(const char* name, char* buffer, int bufsize) { Q_strncpyz(buffer, Cvar::GetValue(name).c_str(), bufsize); }
void trap_Cvar_AddFlags(const char*, int) {}

// ---- commands: registration only ----
namespace Cmd {
void AddCommand(const std::string&, const Cmd::CmdBase&, std::string) {}
void RemoveCommand(const std::string&) {}
}
void trap_AddCommand(const char*) {}
void trap_RemoveCommand(const char*) {}

// ---- FS::PakPath::ReadFile (BUILD_VM branch is an IPC call too) ----
namespace FS { namespace PakPath {
std::string ReadFile(Str::StringRef path, std::error_code& err) {
	auto it = Files().find(path);
	if (it == Files().end()) {
		err = std::make_error_code(std::errc::no_such_file_or_directory);
		return "";
	}
	err.clear();
	return it->second;
}
}}

// Target of the generated stubs (mayhem/gen_engine_stubs.py).
extern "C" [[noreturn]] void unv_fuzz_engine_stub_called(const char* sym) {
	fprintf(stderr, "fuzz engine shim: unexpected engine call %s\n", sym);
	abort();
}
